import {processCases,moltenCases,ionBehaviour,productsCorrect} from './electro-models.js?v=20261023-physicscomplete01';
import {showElectro} from './electro-scenes.js?v=20261023-physicscomplete01';
const select=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select>`;
export function mountElectroWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={};w.answers[i]=a;const molten=l.widget==='electro-molten',t=(molten?moltenCases:processCases)[i],$=s=>root.querySelector(s);const destinations=[['fixed','Fixed in place'],['cathode','Negative cathode'],['anode','Positive anode']];root.innerHTML=`<p><b>Prediction ${i+1} / 3 · ${t.name}</b></p>`+(molten?`<p>The ions are ${t.cation} and ${t.anion}. Assume inert electrodes. Enter product formulae, using normal digits or subscripts.</p><label class="field-label" for="cathodeProduct">Cathode product formula</label><input class="lab-input" id="cathodeProduct" autocomplete="off" spellcheck="false"><label class="field-label" for="anodeProduct">Anode product formula</label><input class="lab-input" id="anodeProduct" autocomplete="off" spellcheck="false">`:select('electroConduct','Will it conduct?',[['yes','Yes'],['no','No']],a.conduct)+select('electroPositive','Positive ions',destinations,a.positive)+select('electroNegative','Negative ions',destinations,a.negative))+`<button class="secondary" id="checkElectro">Check prediction</button><button class="secondary" id="nextElectro">Next case →</button><p id="electroProgress">${w.passed.length} / 3 predictions correct</p>`;const fields=molten?[['metal','cathodeProduct'],['nonmetal','anodeProduct']]:[['conduct','electroConduct'],['positive','electroPositive'],['negative','electroNegative']];fields.forEach(([k,id])=>{$('#'+id).value=a[k]||'';$('#'+id)[molten?'oninput':'onchange']=e=>{a[k]=e.target.value;save();};});showElectro(molten?'molten':'process',t,w.passed.includes(i));$('#checkElectro').onclick=()=>{const expected=molten?null:ionBehaviour(t.state),ok=molten?productsCorrect(t,a.metal,a.nonmetal):Object.entries(expected).every(([k,v])=>a[k]===v);if(!ok){feedback(molten?'Follow charge: positive metal ions reach the negative cathode. Negative ions reach the positive anode. Enter neutral element formulae; chlorine and bromine are diatomic.':'In a solid the ions are fixed. In molten or dissolved compounds ions can move: positive to negative cathode, negative to positive anode.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showElectro(molten?'molten':'process',t,true);$('#electroProgress').textContent=w.passed.length+' / 3 predictions correct';feedback(molten?'Correct: both neutral product formulae match these molten-compound ions.':'Correct: your conduction and movement predictions agree with the ion model.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextElectro').onclick=()=>{w.task=(i+1)%3;save();mountElectroWidget(l,p,root,{save,done,feedback});};}
